import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const RELEASE='0.37.0';
const EXPECTED='0.36.0';
const payload={"package.json":"","src/data/seed.json":"","src/lib/storage.ts":"","src/data/contractTasks.json":"","src/views/ContractSpending.tsx":"","src/views/ItCosts.tsx":"","src/views/OperationsIntelligence.tsx":"","scripts/extract_contract_tasks_from_audit.py":"","RELEASE_NOTES_0.37.md":"","DATA_AUDIT_0.37.md":"","README_NASADENIE_0.37.txt":""};
const root=process.cwd();
const pkgPath=path.join(root,'package.json');
function fail(message,code=1){console.error('ERROR:',message);process.exit(code)}
if(!fs.existsSync(pkgPath))fail('Spusti installer v koreni projektu.');
let pkg;try{pkg=JSON.parse(fs.readFileSync(pkgPath,'utf8'))}catch{fail('package.json sa nepodarilo nacitat.')}
if(pkg?.name!=='is-riadenie-odboru')fail('Tento priecinok nevyzera ako projekt is-riadenie-odboru.');
const current=String(pkg.version||'');
if(current!==EXPECTED&&current!==RELEASE)console.log(`UPOZORNENIE: installer je testovany pre ${EXPECTED} -> ${RELEASE}. Aktualna verzia: ${current||'nezistena'}.`);
console.log(`IS Riadenie odboru - upgrade na v${RELEASE} (SIT Jan-Jul)`);
const stamp=new Date().toISOString().replace(/[:.]/g,'-');
const backup=path.join(root,`backup-before-v0370-${stamp}`);
fs.mkdirSync(backup,{recursive:true});
let written=0,backed=0;
for(const [rel,encoded] of Object.entries(payload)){
  const destination=path.join(root,rel);
  if(fs.existsSync(destination)){
    const backupPath=path.join(backup,rel);fs.mkdirSync(path.dirname(backupPath),{recursive:true});fs.copyFileSync(destination,backupPath);backed++;
  }
  fs.mkdirSync(path.dirname(destination),{recursive:true});
  fs.writeFileSync(destination,zlib.gunzipSync(Buffer.from(encoded,'base64')));
  console.log('WRITE',rel);written++;
}
for(const cache of ['dist','.vite',path.join('node_modules','.vite')]){const target=path.join(root,cache);if(fs.existsSync(target)){fs.rmSync(target,{recursive:true,force:true});console.log('CLEAR',cache)}}
const checkPkg=JSON.parse(fs.readFileSync(pkgPath,'utf8'));
const tasks=JSON.parse(fs.readFileSync(path.join(root,'src/data/contractTasks.json'),'utf8'));
const byCode=Object.fromEntries((tasks.tasks||[]).map(t=>[String(t.code),t]));
const expected={'10':509559.61,'22':49508.47,'25':48541.18};
if(checkPkg.version!==RELEASE)fail('Kontrola verzie zlyhala.',2);
if(Number(tasks?.meta?.monthsLoaded)!==7)fail('contractTasks nema 7 nacitanych mesiacov.',3);
for(const [code,value] of Object.entries(expected))if(Math.abs(Number(byCode[code]?.spent||0)-value)>0.01)fail(`Kontrola ulohy ${code} zlyhala.`,4);
const total=Object.values(expected).reduce((a,b)=>a+b,0);
const actual=(tasks.tasks||[]).reduce((sum,t)=>sum+Number(t.spent||0),0);
if(Math.abs(actual-total)>0.01)fail('Kontrola celkoveho cerpania zlyhala.',5);
console.log('');
console.log(`VERIFIED: v${RELEASE} SIT Jan-Jul je nainstalovane.`);
console.log(`Suborov zapisanych: ${written}, zalohovanych: ${backed}.`);
console.log('Zaloha:',backup);
console.log('Novy Supabase SQL sa nespusta.');
console.log('Dodavatelsky ledger sa tymto releasom nemeni.');
